from pathlib import Path

root = Path(__file__).parent
html = (root / 'index.html').read_text(encoding='utf-8')
html = html.replace('purchasing-flow-v1', 'purchasing-flow-settings-v2-analysis')
html = html.replace("location.hash.slice(1)||'flow'", "location.hash.slice(1)||'setting'")
html = html.replace('<title>원료 구매 분석 | 한화첨단소재</title>', '<title>원료·구성비 설정 v2 | 한화첨단소재</title>')
css = '''
.blend-selection{display:grid;grid-template-columns:1fr 1fr;gap:20px}.blend-selection select{width:100%}.blend-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:20px 0}.blend-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.blend-fields .wide{grid-column:1/-1}.blend-fields input,.blend-fields select{width:100%;min-width:0}.blend-price{font-size:26px;font-weight:700;margin:12px 0 3px}.blend-source{min-height:65px;font-size:12px;color:var(--muted)}.blend-summary{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px}.ratio-bar{height:10px;background:#edf1f3;display:flex;border-radius:10px;overflow:hidden;margin:14px 0}.ratio-bar i{display:block}.add-material{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:300px;border:2px dashed #cad7df;border-radius:10px;background:transparent;gap:10px;color:var(--muted)}.add-material strong{font-size:18px;color:var(--ink)}.add-material span:first-child{font-size:30px;color:var(--orange)}button:disabled{opacity:.45;cursor:not-allowed}.blend-toolbar{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap;margin-top:20px}.blend-summary table{font-size:13px}.blend-reference td,.blend-reference th{font-size:12px}.blend-reference small{display:block;color:var(--muted)}.blend-alert{font-size:12px;color:#99612d;background:#fff8ed;padding:12px;border-radius:6px;margin-top:12px}@media(max-width:1000px){.blend-grid,.blend-summary{grid-template-columns:1fr}}@media(max-width:650px){.blend-selection,.blend-fields{grid-template-columns:1fr}.blend-fields .wide{grid-column:auto}}
'''
html = html.replace('</style>', css + '</style>')
start = html.index('function settingPage()')
end = html.index('function cPage()', start)
settings = r'''
const ingredientCatalog={
 pp:{name:'PP',price:1.58,note:'参考表1: 1.58 USD/kg · 表2: 1,576 USD/MT (= 1.576 USD/kg)'.replace('参考表1','참고 표 1').replace('表2','표 2'),details:'Ethylene propylene copolymer (에틸렌 프로필렌 공중합체)'},
 glassmat:{name:'유리섬유 매트 (강화재)',price:1.90,note:'참고 표 1·2: 1.90 USD/kg',details:'유리 · 커플링제 · 피막형성제 · 고분자 수지/에멀전'},
 antistatic:{name:'대전방지제',price:3.69,note:'참고 표 1·2: 3.69 USD/kg',details:'PEBA · 폴리에틸렌 에스테르 공중합체 · PEO 기반 특수 공중합체'},
 polyester:{name:'불포화 폴리에스터 수지',price:3.53,note:'참고 표 1: 3.53 USD/kg · 표 2: 3,529 USD/MT',details:'무수말레산·푸마르산, 무수프탈산·이소프탈산, PG·EG·NPG, 스티렌 모노머'},
 filler:{name:'탄산칼슘 (충진제)',price:.34,note:'참고 표 1·2: 0.34 USD/kg (= 340 USD/MT)',details:'중질 탄산칼슘 (GCC) · 스테아르산 등 지방산류 (표면 처리제)'},
 glass:{name:'유리섬유',price:.79,note:'참고 표 1·2: 0.79 USD/kg',details:'무알칼리 유리 · 실란 커플링제 · 에멀전 · 윤활제 및 대전방지제'},
 other:{name:'촉매/이형제 등 기타',price:null,note:'참고 표: 메인 기반 · 단가 직접 입력',details:'참고 표 1의 총괄 항목; 개별 단가 미기재'},
 pvc:{name:'PVC (가소화)',price:1.57,note:'참고 표 1: 1.57 USD/kg',details:'IntermLite (PVC) 투입 원재료'},
 tpo:{name:'TPO',price:2.68,note:'참고 표 1: 2.68 USD/kg',details:'IntermLite (TPO) 투입 원재료'},
 tpu:{name:'TPU',price:4.26,note:'참고 표 1: 4.26 USD/kg',details:'IntermLite (TPU) 투입 원재료'},
 biotpo:{name:'바이오 및 리사이클 TPO',price:2.68,note:'참고 표 1: 2.68 USD/kg',details:'IntermLite (Bio/Re) 투입 원재료'},
 slurry:{name:'Resin/Glass Slurry',price:null,note:'참고 표 2: 단가 미기재 · 직접 입력',details:'SuperLite (LWRT) 투입 원재료'},
 scrim:{name:'Scrim',price:null,note:'참고 표 2: 단가 미기재 · 직접 입력',details:'SuperLite (LWRT) 투입 원재료'},
 film:{name:'Film',price:null,note:'참고 표 2: 단가 미기재 · 직접 입력',details:'SuperLite (LWRT) 투입 원재료'}
};
const productCatalog={
 strong:{name:'StrongLite (GMT)',business:'자동차 경량복합소재',rows:[['pp',60],['glassmat',40]]},
 buff:{name:'BuffLite (EPP)',business:'자동차 경량복합소재',rows:[['pp',95],['antistatic',5]]},
 super:{name:'SuperLite (LWRT)',business:'자동차 경량복합소재',rows:[['slurry',50],['scrim',50]]},
 smc:{name:'SMC',business:'자동차 경량복합소재',rows:[['polyester',30],['filler',40]]},
 pvc:{name:'IntermLite (PVC)',business:'자동차 내장재',rows:[['pvc',100]]},
 tpo:{name:'IntermLite (TPO)',business:'자동차 내장재',rows:[['tpo',100]]},
 tpu:{name:'IntermLite (TPU)',business:'자동차 내장재',rows:[['tpu',100]]},
 bio:{name:'IntermLite (Bio/Re)',business:'자동차 내장재',rows:[['biotpo',100]]}
};
function defaultBlend(product){return {product,rows:productCatalog[product].rows.map(([key,ratio])=>({key,ratio,price:ingredientCatalog[key].price,unit:'kg'}))}}
let blend=defaultBlend('strong');
try{const saved=JSON.parse(localStorage.getItem('purchasing-blend-v2')||'null');if(saved&&productCatalog[saved.product]&&Array.isArray(saved.rows)&&saved.rows.length>=1&&saved.rows.length<=2&&saved.rows.every(r=>ingredientCatalog[r.key]&&['kg','mt'].includes(r.unit)&&Number.isFinite(r.ratio)&&r.ratio>=0&&r.ratio<=100&&(r.price===null||Number.isFinite(r.price)&&r.price>=0)))blend=saved}catch(e){}
function escapeText(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function blendCost(row){return row.price===null?null:row.price/(row.unit==='mt'?1000:1)*row.ratio/100}
function blendCheck(){let ratio=blend.rows.reduce((s,r)=>s+r.ratio,0),total=blend.rows.reduce((s,r)=>s+(blendCost(r)||0),0),duplicates=new Set(blend.rows.map(r=>r.key)).size!==blend.rows.length;let prices=blend.rows.every(r=>r.price!==null&&Number.isFinite(r.price)&&r.price>=0);let ratios=blend.rows.every(r=>Number.isFinite(r.ratio)&&r.ratio>0&&r.ratio<=100);let valid=blend.rows.length>=1&&blend.rows.length<=2&&Math.abs(ratio-100)<.000001&&prices&&ratios&&!duplicates;let issue=duplicates?'동일한 원료를 중복 선택할 수 없습니다.':!ratios?'선택 원료의 비중을 0% 초과로 입력하세요.':!prices?'모든 원료의 단가를 입력하세요.':Math.abs(ratio-100)>=.000001?'배합 비중의 합계를 100%로 맞춰주세요.':'';return {ratio,total,valid,issue}}
function addBlendRow(){if(blend.rows.length>=2)return;let key=Object.keys(ingredientCatalog).find(k=>!blend.rows.some(r=>r.key===k));blend.rows.push({key,ratio:0,price:ingredientCatalog[key].price,unit:'kg'})}
function settingPage(){let product=productCatalog[blend.product],check=blendCheck();return heading('01','원료와 구성비 설정','사업 부문과 제품을 선택하고, 최대 2개 원료의 단가·배합 비중을 설정합니다.')+`<section class="card"><div class="blend-selection"><label>사업 부문<select id="blendBusiness">${['자동차 경량복합소재','자동차 내장재'].map(b=>`<option ${b===product.business?'selected':''}>${b}</option>`).join('')}</select></label><label>주요 제품<select id="blendProduct">${Object.entries(productCatalog).filter(([k,p])=>p.business===product.business).map(([k,p])=>`<option value="${k}" ${k===blend.product?'selected':''}>${p.name}</option>`).join('')}</select></label></div><div class="blend-alert">첨부 참고 표의 단가·비중을 초기값으로 사용합니다. 최신 시장가가 아니며 입력값은 수정할 수 있습니다. ${blend.product==='smc'?'SMC의 원래 배합은 4개 원료입니다. 현재는 첫 2개 원료(30%·40%)만 불러오므로 분석할 2개와 비중을 직접 정해야 합니다.':blend.product==='super'?'SuperLite의 참고 표에는 비중·단가가 없습니다. 비중 50%·50%는 편집용 초기값이며 단가는 직접 입력해야 합니다.':''}</div></section><div class="blend-grid">${blend.rows.map((row,i)=>{let raw=ingredientCatalog[row.key];return `<section class="card"><div class="cardhead"><h2>원료 ${i+1}</h2>${blend.rows.length>1?`<button type="button" class="button" data-remove="${i}">삭제</button>`:'<span class="tag">필수 원료</span>'}</div><div class="blend-fields"><label class="wide">투입 원재료<select data-row="${i}" data-field="key">${Object.entries(ingredientCatalog).map(([k,r])=>`<option value="${k}" ${k===row.key?'selected':''} ${blend.rows.some((x,j)=>j!==i&&x.key===k)?'disabled':''}>${r.name}</option>`).join('')}</select></label><label>기준 단가<input type="number" min="0" step="any" data-row="${i}" data-field="price" value="${row.price===null?'':row.price}" placeholder="단가 입력"></label><label>단가 단위<select data-row="${i}" data-field="unit"><option value="kg" ${row.unit==='kg'?'selected':''}>USD/kg</option><option value="mt" ${row.unit==='mt'?'selected':''}>USD/MT</option></select></label><label class="wide">배합 비중 (%)<input type="number" min="0" max="100" step="any" data-row="${i}" data-field="ratio" value="${row.ratio}"></label></div><p class="blend-source">${raw.note}<br>${raw.details}</p><div class="explain">제품 1kg당 원료별 금액 <strong>${blendCost(row)===null?'미입력':fmt(blendCost(row),4)+' USD'}</strong></div></section>`}).join('')}${blend.rows.length===1?'<button class="add-material" type="button" id="addBlend"><span>＋</span><strong>두 번째 원료 추가</strong><span>최대 2개 원료까지 설정할 수 있습니다.</span></button>':''}</div><div class="blend-summary"><section class="card"><div class="cardhead"><h2>배합 비중</h2><span class="tag">${blend.rows.length} / 2개</span></div><div class="ratio-bar">${blend.rows.map((r,i)=>`<i style="width:${Math.min(100,Math.max(0,r.ratio))}%;background:${i?'#397eac':'#eb6d24'}"></i>`).join('')}</div>${blend.rows.map((r,i)=>`<p>${i+1}. ${ingredientCatalog[r.key].name} <strong>${fmt(r.ratio,2)}%</strong></p>`).join('')}<div class="status ${check.valid?'':'negative'}">합계 ${fmt(check.ratio,2)}% · ${check.valid?'설정 가능':check.issue}</div></section><section class="card"><h2>제품 1kg당 총 투입 원가</h2><div class="blend-price">${check.valid?fmt(check.total,4)+' USD':'설정 확인 필요'}</div><p>${check.valid?'표시용 반올림: '+fmt(check.total,2)+' USD/kg':'비중 합계와 단가를 확인하면 총 투입 원가를 표시합니다.'}</p><div class="explain">합계 = Σ(기준 단가 USD/kg × 배합 비중 ÷ 100). USD/MT는 1,000으로 나눠 환산합니다. 가공비·운임·관세·수율 손실은 포함하지 않습니다.</div></section></div><section class="card blend-reference" style="margin-top:20px"><h2>원료별 계산 내역</h2><div class="tablewrap"><table><thead><tr><th>사업 부문</th><th>주요 제품</th><th>투입 원재료</th><th>기준 단가</th><th>배합 비중</th><th>원료별 금액 / 제품 kg</th></tr></thead><tbody>${blend.rows.map(r=>`<tr><td>${product.business}</td><td>${product.name}</td><td>${ingredientCatalog[r.key].name}</td><td>${r.price===null?'미입력':fmt(r.price,4)+' USD/'+(r.unit==='mt'?'MT':'kg')}</td><td>${fmt(r.ratio,2)}%</td><td>${blendCost(r)===null?'미입력':fmt(blendCost(r),4)+' USD'}</td></tr>`).join('')}</tbody></table></div></section><div class="blend-toolbar"><span class="small" id="blendSaveStatus" role="status">변경 내용은 ‘설정 저장’을 눌러 저장합니다.</span><button id="saveBlend" class="button primary" type="button" ${check.valid?'':'disabled'}>설정 저장</button></div><div class="explain">참고 표의 ‘투입 원재료’를 선택 원료 단위로 사용합니다. 상세 성분은 참고 설명으로만 표시합니다. a/b 분석 화면은 기존 PP·EVA 예시 데이터이며, 이 제품 배합 계산과의 실제 데이터 연결은 후속 작업입니다.</div>`+actions('flow','a1','전체 플로우','시장가·실적 비교')}
function bindBlend(){document.querySelectorAll('[data-row]').forEach(el=>el.addEventListener('change',()=>{let row=blend.rows[Number(el.dataset.row)],field=el.dataset.field;if(field==='key'){row.key=el.value;row.price=ingredientCatalog[el.value].price;row.unit='kg'}else if(field==='unit'){if(row.price!==null)row.price=el.value==='mt'?row.price*1000:row.price/1000;row.unit=el.value}else{if(!el.checkValidity()){el.reportValidity();return}row[field]=el.value===''?(field==='price'?null:0):Number(el.value)}render()}));document.querySelectorAll('[data-remove]').forEach(el=>el.addEventListener('click',()=>{if(blend.rows.length>1)blend.rows.splice(Number(el.dataset.remove),1);render()}));const add=document.getElementById('addBlend');if(add)add.addEventListener('click',()=>{addBlendRow();render()});const business=document.getElementById('blendBusiness');if(business)business.addEventListener('change',()=>{blend=defaultBlend(Object.keys(productCatalog).find(k=>productCatalog[k].business===business.value));render()});const product=document.getElementById('blendProduct');if(product)product.addEventListener('change',()=>{blend=defaultBlend(product.value);render()});const save=document.getElementById('saveBlend');if(save)save.addEventListener('click',()=>{if(!blendCheck().valid)return;try{localStorage.setItem('purchasing-blend-v2',JSON.stringify(blend));document.getElementById('blendSaveStatus').textContent='설정을 저장했습니다. 다시 열면 저장한 배합을 불러옵니다.'}catch(e){document.getElementById('blendSaveStatus').textContent='브라우저 저장이 제한되어 저장하지 못했습니다.'}})}
'''
html = html[:start] + settings + '\n' + html[end:]
html = html.replace('window.addEventListener(\'hashchange\'', "const renderOriginal=render;render=function(){renderOriginal();if((location.hash.slice(1)||'setting')==='setting')bindBlend()};\nwindow.addEventListener('hashchange'")
html = html.replace('모든 수치와 뉴스 제목은 가상 예시입니다.', '분석 차트·뉴스는 가상 예시 · 설정 단가·비중은 첨부 참고 표 기준입니다.')
(root / '원료구성비설정_v2.html').write_text(html, encoding='utf-8')
print('Created:', root / '원료구성비설정_v2.html')
